package io.github.rebrowser.data;
import org.junit.Test;
import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.ComponentGate;
import io.github.rebrowser.settings.SettingsRepository;
import io.github.rebrowser.browser.SearchEngines;
import java.nio.file.*;
import java.util.concurrent.atomic.AtomicInteger;
/** Real HOST file/JCA/CAS phases, explicitly synthetic current-domain fences; no OS authority. */
public final class NativeRecordWriteFenceTest {
 static byte[] intended(){return SettingsRepository.CODEC.encode(new SettingsRepository.Snapshot(1,SearchEngines.Provider.GOOGLE,false,false));}
 @Test public void currentAuthorityRepeatedAfterActualFileForceBeforeReplacement()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){f.seedSettings(true);PrivateRecordStore.Reference ref=f.ref(OwnedDataCatalog.Family.SETTINGS);Path path=f.root.resolve(ref.opaqueRef());byte[] original=Files.readAllBytes(path);AtomicInteger checks=new AtomicInteger();try(PrivateRecordStore.ReadRecord read=f.records.read(ref,f.permit)){assertThrows(SecurityException.class,()->f.records.writeAfterNativeAuthorization(read.stamp(),intended(),f.permit,()->{if(checks.incrementAndGet()==2)throw new SecurityException("synthetic native owner grant revoked after force");}));}assertEquals(2,checks.get());assertArrayEquals(original,Files.readAllBytes(path));assertTrue(Files.isRegularFile(f.root.resolve(ref.opaqueRef()+".pending")));assertFalse(f.records.hasOwnedIoInFlight());}}
 @Test public void equalEpochCutoverDuringCommitFenceCannotPreserveOldPermit()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){f.seedSettings(true);PrivateRecordStore.Reference ref=f.ref(OwnedDataCatalog.Family.SETTINGS);Path path=f.root.resolve(ref.opaqueRef());byte[] original=Files.readAllBytes(path);AtomicInteger checks=new AtomicInteger();try(PrivateRecordStore.ReadRecord read=f.records.read(ref,f.permit)){assertThrows(SecurityException.class,()->f.records.writeAfterNativeAuthorization(read.stamp(),intended(),f.permit,()->{if(checks.incrementAndGet()==2)f.source.set(ComponentGate.SourceView.acceptedNative(new Object(),new byte[16]));}));}assertArrayEquals(original,Files.readAllBytes(path));}}
 @Test public void postReadbackFenceFailureIsUnknownNotAutomaticReplay()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F()){f.seedSettings(true);PrivateRecordStore.Reference ref=f.ref(OwnedDataCatalog.Family.SETTINGS);AtomicInteger checks=new AtomicInteger();try(PrivateRecordStore.ReadRecord read=f.records.read(ref,f.permit)){assertThrows(SecurityException.class,()->f.records.writeAfterNativeAuthorization(read.stamp(),intended(),f.permit,()->{if(checks.incrementAndGet()==3)throw new SecurityException("synthetic post-CAS revocation");}));assertThrows(java.io.IOException.class,()->f.records.writeAfterNativeAuthorization(read.stamp(),intended(),f.permit,()->{}));}try(PrivateRecordStore.ReadRecord actual=f.records.read(ref,f.permit)){SettingsRepository.Snapshot saved=actual.readOwnedPlaintext(SettingsRepository.CODEC::decode);assertEquals(SearchEngines.Provider.GOOGLE,saved.searchProvider());}assertEquals(3,checks.get());}}
 @Test public void missingNativeFenceIsNotAnAuthorizationDefault()throws Exception{try(BrowserMetadataStoreTest.F f=new BrowserMetadataStoreTest.F();PrivateRecordStore.ReadRecord read=f.records.read(f.ref(OwnedDataCatalog.Family.SETTINGS),f.permit)){assertThrows(IllegalArgumentException.class,()->f.records.writeAfterNativeAuthorization(read.stamp(),intended(),f.permit,null));assertFalse(f.records.hasOwnedIoInFlight());}}
}
